const transactions = $input.all().map(item => item.json);

const amounts = transactions
  .map(t => Number(t.amount) || 0)
  .filter(amount => amount > 0);

if (amounts.length === 0) {
  return [
    {
      json: {
        transaction_count: 0,
        average_expense: 0,
        transactions: []
      }
    }
  ];
}

const average =
  amounts.reduce((sum, amount) => sum + amount, 0) / amounts.length;

const sortedAmounts = [...amounts].sort((a, b) => a - b);

const median =
  sortedAmounts.length % 2 === 0
    ? (sortedAmounts[sortedAmounts.length / 2 - 1] +
       sortedAmounts[sortedAmounts.length / 2]) / 2
    : sortedAmounts[Math.floor(sortedAmounts.length / 2)];

const analyzedTransactions = transactions.map(transaction => {
  const amount = Number(transaction.amount) || 0;

  return {
    date: transaction.transaction_date,
    merchant: transaction.merchant,
    amount,
    category: transaction.category,
    subcategory: transaction.subcategory,
    compared_to_average:
      average > 0
        ? Number((amount / average).toFixed(2))
        : 0
  };
});

return [
  {
    json: {
      transaction_count: transactions.length,
      average_expense: Number(average.toFixed(2)),
      median_expense: Number(median.toFixed(2)),
      transactions: analyzedTransactions
    }
  }
];

const output = $json.output;

let result;

if (typeof output === 'string') {
  result = JSON.parse(output);
} else {
  result = output;
}

return [
  {
    json: result
  }
];
